const quartzFields = `data_quartz_rounded_teaching_excerpt
_space_group_IT_number 154
_symmetry_Int_Tables_number 154
_cell_length_a 4.91239(4)
_cell_length_b 4.91239(4)
_cell_length_c 5.40385(7)
_cell_angle_alpha 90
_cell_angle_beta 90
_cell_angle_gamma 120
loop_
_symmetry_equiv_pos_as_xyz
x,y,z
-y,x-y,2/3+z
y-x,-x,1/3+z
y,x,-z
x-y,-y,1/3-z
-x,y-x,2/3-z
loop_
_atom_site_label
_atom_site_type_symbol
_atom_site_symmetry_multiplicity
_atom_site_fract_x
_atom_site_fract_y
_atom_site_fract_z
_atom_site_occupancy
Si1 Si4+ 3 0.4701(4) 0. 0.6667 1.
O1 O2- 6 0.4139(7) 0.2674(7) 0.7856(6) 1.
`;

export const cifOrbitCases = Object.freeze([
  Object.freeze({id:'rounded', filename:'quartz_rounded_teaching_excerpt.cif', text:quartzFields}),
  Object.freeze({id:'exact', filename:'quartz_exact_teaching_control.cif', text:quartzFields
    .replace('data_quartz_rounded_teaching_excerpt','data_quartz_exact_teaching_control')
    .replace('0. 0.6667 1.','0. 2/3 1.')})
]);

export function cifOrbitPracticeEnabled(query){
  const values=new URLSearchParams(query).getAll('cif-orbit');
  return values.length===1&&values[0]==='practice';
}

export function cifOrbitPracticeHTML(open){
  return `<details class="structure-details" id="structure-cif-orbit-practice"${open?' open':''}>
    <summary>α-Quartz · Check the multiplicity of a site orbit</summary>
    <p>The declared multiplicity of Si1 is 3. Predict whether changing the third fractional coordinate from <code>0.6667</code> to <code>2/3</code>changes the number of distinct periodic sites generated by the six operations.</p>
    <div class="controls-row">
      <button type="button" id="structure-cif-orbit-practice-rounded" class="secondary small" data-cif-orbit-case="rounded">Load the rounded quartz coordinates</button>
      <button type="button" id="structure-cif-orbit-practice-exact" class="secondary small" data-cif-orbit-case="exact">Load the exact-coordinate control</button>
    </div>
    <p id="structure-cif-orbit-practice-status" class="form-note" role="status" tabindex="-1" hidden></p>
    <details class="structure-details"><summary>Check your prediction</summary><p>The rounded coordinate splits the images of Si1 into six sites. Import reports the difference between the declared and calculated counts. The exact control produces three Si sites and six O sites. Both calculations use the same space-group operations.</p></details>
    <p class="form-note">The rounded input reproduces selected fields from the original structure. The exact control uses this site's fraction syntax to replace one coordinate in the teaching copy. Standard CIF numeric fields use integers or decimal numbers.</p>
    <p class="controls-row"><a href="#classroom/crystal?track=space&amp;tab=learn&amp;lesson=space-04">Return to the site symmetry lesson →</a><a href="https://www.crystallography.net/cod/5000035.html" target="_blank" rel="noreferrer">Original structure and source ↗</a></p>
  </details>`;
}
